#include "stack.h"
#include <cassert>
#include <iostream>

int main() {
    Stack s;
    assert(s.isEmpty());
    assert(!s.isFull());

    s.push(10);
    s.push(20);
    s.push(30);
    assert(!s.isEmpty());
    assert(s.peek() == 30);
    assert(s.pop() == 30);
    assert(s.peek() == 20);
    assert(s.pop() == 20);
    assert(s.pop() == 10);
    assert(s.isEmpty());

    for (int i = 0; i < 100; i++) {
        s.push(i);
    }
    assert(s.isFull());
    assert(s.peek() == 99);

    std::cout << "PASS" << std::endl;
    return 0;
}

