#pragma once

class Stack {
public:
    Stack() : top_(0) {}

    void push(int value) {
        if (!isFull()) data_[top_++] = value;
    }

    int pop() {
        return data_[--top_];
    }

    int peek() const {
        return data_[top_ - 1];
    }

    bool isEmpty() const {
        return top_ == 0;
    }

    bool isFull() const {
        return top_ == 100;
    }

private:
    int data_[100];
    int top_;
};
